function openDialog(title,body){photoJob++;stopCamera();dialog.innerHTML=`<header class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" type="button" data-action="dialog-close" aria-label="Fechar janela">${icon('close')}</button></header><div class="dialog-body"><div id="dialog-error" role="alert" hidden></div>${body}</div>`;if(!dialog.open)dialog.showModal();}
function dialogError(message){const box=document.getElementById('dialog-error');if(box){box.textContent=message;box.className='dialog-error';box.hidden=false;box.scrollIntoView({block:'nearest'});}else notify(message,true);}
function showProfile(id){const a=athlete(id),s=getAthleteSkills(state,id,modality),keys=s.isGoalkeeper?['div','han','kic','ref','spd','pos']:['rit','fin','pas','con','def','fis'],labels={rit:'Ritmo',fin:'Finalização',pas:'Passe',con:'Controle',def:'Marcação',fis:'Físico',div:'Defesa',han:'Segurança',kic:'Reposição',ref:'Reflexos',spd:'Velocidade',pos:'Posicionamento'},stats=state.rounds.filter(r=>r.status==='closed'&&r.modality===modality).flatMap(r=>getRoundStats(state,r.id)).filter(r=>r.athleteId===id);openDialog(e(a.nickname||a.name),`<div class="profile-layout"><div class="profile-card">${card(a)}</div><div><div class="eyebrow">${e(MODALITIES[modality].label)} · ${e(positionOf(a,modality))}</div><h2>${e(a.name)}</h2><p class="subtitle">${e(a.contact)}</p><div class="skill-list">${keys.map(k=>`<div class="skill-row"><strong><span>${labels[k]}</span><span>${s[k]}</span></strong><div class="skill-track"><i style="width:${s[k]}%"></i></div></div>`).join('')}</div><p class="footnote">${stats.reduce((n,r)=>n+(r.playedMatches||0),0)} jogos encerrados · ${stats.reduce((n,r)=>n+(r.goals||0),0)} gols · ${stats.reduce((n,r)=>n+(r.assists||0),0)} assistências</p><p class="footnote">Skills por modalidade. Ritmo, controle e físico ficam na avaliação inicial nesta versão; os lances registrados evoluem os atributos correspondentes.</p><div class="form-actions">${!accounts.current||isOrganizer()||id===accounts.current.athleteId?button(`${icon('edit')} Editar perfil`,'edit-athlete','',`data-id="${e(id)}"`):''}</div></div></div>`);}
function athleteForm(id){const a=id?athlete(id):null;photoDraft=a?.photo||'';openDialog(a?'Editar atleta':'Novo parça',`<form id="athlete-form" data-id="${e(id||'')}"><div class="form-grid"><div class="field"><label for="athlete-name">Nome completo</label><input class="input" id="athlete-name" name="name" required maxlength="80" value="${e(a?.name)}"></div><div class="field"><label for="athlete-nickname">Apelido no card</label><input class="input" id="athlete-nickname" name="nickname" required maxlength="18" value="${e(a?.nickname)}"></div><div class="field full"><label for="athlete-contact">E-mail ou telefone</label><input class="input" id="athlete-contact" name="contact" required maxlength="100" value="${e(a?.contact)}"><p class="field-help">Contato visível para os membros da sua turma.</p></div><div class="field full"><label>Foto do card</label><div class="photo-options"><img id="photo-preview" class="photo-preview" alt="Prévia da foto" src="${e(photoDraft||'./logo-fut-parca.jpeg')}"><label class="button secondary file-button">${icon('plus')} Enviar foto<input type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp" aria-label="Enviar foto do atleta"></label>${button(`${icon('camera')} Tirar foto`,'camera','secondary')}</div><div id="camera-box" hidden class="space-top"><video id="camera-video" class="camera" autoplay playsinline muted></video><div class="row">${button(`${icon('camera')} Capturar foto`,'capture-photo')}${button('Cancelar câmera','stop-camera','secondary')}</div></div><p class="field-help">JPG, PNG ou WebP. Foto transparente fica melhor no card dourado.</p></div>${Object.entries(MODALITIES).map(([m,x])=>`<div class="field"><label for="primary-${m}">${e(x.label)} · posição principal</label><select class="input" id="primary-${m}" name="primary-${m}">${x.positions.map(p=>`<option ${p===(a?.preferences?.[m]?.primary||({futebol:'Meia',futsal:'Ala',society:'Meio-campista'}[m]))?'selected':''}>${e(p)}</option>`).join('')}</select></div><div class="field"><label for="secondary-${m}">${e(x.label)} · posição secundária</label><select class="input" id="secondary-${m}" name="secondary-${m}"><option value="">Sem preferência</option>${x.positions.map(p=>`<option ${p===a?.preferences?.[m]?.secondary?'selected':''}>${e(p)}</option>`).join('')}</select></div>`).join('')}</div><div class="form-actions">${button('Cancelar','dialog-close','secondary')}<button class="button" type="submit">${icon('save')} Salvar atleta</button></div></form>`);}
async function resizePhoto(file){if(file.size>12000000)throw new Error('Escolha uma foto com até 12 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use uma imagem JPG, PNG ou WebP.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,560/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let result=canvas.toDataURL('image/webp',.78);if(result.length>1900000)result=canvas.toDataURL('image/jpeg',.68);if(result.length>2500000)throw new Error('Não foi possível reduzir esta foto. Escolha outra imagem.');return result;}
function updatePhoto(data){photoDraft=data;const img=document.getElementById('photo-preview');if(img)img.src=data;}
function stopCamera(){cameraJob++;openingCamera=false;cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;const video=document.getElementById('camera-video');if(video)video.srcObject=null;const box=document.getElementById('camera-box');if(box)box.hidden=true;}
async function startCamera(){
 if(openingCamera||cameraStream)return;
 const job=++cameraJob,video=document.getElementById('camera-video'),box=document.getElementById('camera-box');openingCamera=true;
 try{
  if(!navigator.mediaDevices?.getUserMedia)throw new Error('Câmera indisponível neste navegador. Use Enviar foto.');
  const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});
  if(job!==cameraJob||!dialog.open||!video?.isConnected){stream.getTracks().forEach(t=>t.stop());return;}
  cameraStream=stream;box.hidden=false;video.srcObject=stream;
 }catch(err){if(job===cameraJob)dialogError(err.name==='NotAllowedError'?'Autorize a câmera no navegador ou envie uma foto.':err.message);}
 finally{if(job===cameraJob)openingCamera=false;}
}
async function uploadPhoto(file){
 const form=dialog.querySelector('#athlete-form');if(!form)return;
 const job=++photoJob,submit=form.querySelector('[type="submit"]');submit.disabled=true;form.dataset.photoBusy='1';
 try{const data=await resizePhoto(file);if(job===photoJob&&dialog.open&&form===dialog.querySelector('#athlete-form'))updatePhoto(data);}
 catch(err){if(job===photoJob&&dialog.open)dialogError(err.message);}
 finally{if(job===photoJob&&form.isConnected){submit.disabled=false;delete form.dataset.photoBusy;}}
}
function capturePhoto(){const video=document.getElementById('camera-video');if(!video.videoWidth)return dialogError('Aguarde a imagem da câmera.');const canvas=document.createElement('canvas'),scale=Math.min(1,720/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);photoJob++;const form=dialog.querySelector('#athlete-form');if(form){form.querySelector('[type="submit"]').disabled=false;delete form.dataset.photoBusy;}updatePhoto(canvas.toDataURL('image/webp',.86));stopCamera();notify('Foto capturada. Salve o perfil para confirmar.');}
function fantasyForm(id){const r=round(),t=r.fantasy.find(t=>t.id===id),confirmed=[...new Set(r.teams.flatMap(t=>t.athleteIds))],size={futsal:5,society:7,futebol:11}[r.modality];openDialog(t?'Editar escalação':'Escalar meu time',`<form id="fantasy-form" data-id="${e(id||'')}"><div class="form-grid"><div class="field"><label for="fantasy-name">Nome do time</label><input class="input" id="fantasy-name" name="name" required maxlength="45" value="${e(t?.name)}"></div><div class="field"><label for="fantasy-owner">Seu nome</label><input class="input" id="fantasy-owner" name="owner" required maxlength="50" value="${e(t?.owner||accounts.current?.user.name)}" ${accounts.current&&!isOrganizer()?'readonly':''}></div></div><div class="row spread space-top" style="margin-bottom:13px"><h3>Escolha ${size} atletas, incluindo 1 goleiro</h3><span id="selected-count" class="selected-count">${t?.athleteIds.length||0}/${size}</span></div><div class="check-list">${confirmed.map(id=>{const a=athlete(id),s=getAthleteSkills(state,id,r.modality);return `<label class="check-person"><input type="checkbox" name="athleteIds" value="${e(id)}" ${t?.athleteIds.includes(id)?'checked':''}><div><strong>${e(a.nickname||a.name)}</strong><span>${e(positionForRound(state,r,a.id))}</span></div><span class="cost">${s.overall}</span></label>`;}).join('')}</div><p class="field-help">Sem limite de orçamento nesta primeira versão. A escalação trava quando a pelada começa.</p><div class="form-actions">${button('Cancelar','dialog-close','secondary')}<button type="submit" class="button">${icon('check')} Confirmar escalação</button></div></form>`);}
function plannedSchedule(){const group=accounts.current?.group||{},type=group.scheduleType||'recurring';if(type==='single')return {type,date:group.singleDate,time:group.singleTime,label:'Pelada avulsa · acontece uma única vez'};const weekday={Domingo:0,Segunda:1,Terça:2,Quarta:3,Quinta:4,Sexta:5,Sábado:6}[group.weeklyDay]??new Date().getDay(),today=new Date();today.setHours(12,0,0,0);const last=state.rounds.map(r=>r.date).filter(Boolean).sort().at(-1);let next=last?new Date(`${last}T12:00:00`):new Date(today);if(last&&next>=today)next.setDate(next.getDate()+7);else{next=new Date(today);next.setDate(next.getDate()+(weekday-next.getDay()+7)%7);}return {type,date:isoDate(next),time:group.weeklyTime||'20:00',label:`Pelada fixa · toda ${String(group.weeklyDay||'semana').toLocaleLowerCase('pt-BR')}`};}
function roundForm(){const schedule=plannedSchedule();if(schedule.type==='single'&&state.rounds.length)return notify('Esta pelada é avulsa e já possui seu único evento.',true);openDialog('Nova pelada',`<form id="round-form"><input type="hidden" name="date" value="${e(schedule.date)}"><input type="hidden" name="time" value="${e(schedule.time)}"><div class="notice"><strong>${e(schedule.label)}</strong><br>${schedule.date?`${date(schedule.date)} às ${e(schedule.time)}`:'Confira a data e o horário nas configurações da pelada.'}</div><div class="form-grid space-top"><div class="field full"><label for="round-title">Nome do evento</label><input class="input" id="round-title" name="title" required maxlength="70" value="${e(accounts.current?.group.name||'Pelada dos Parças')}"></div><div class="field"><label for="round-modality">Modalidade</label><select class="input" id="round-modality" name="modality">${Object.entries(MODALITIES).map(([id,m])=>`<option value="${id}" ${id===modality?'selected':''}>${e(m.label)}</option>`).join('')}</select></div><div class="field"><label for="team-count">Quantidade de equipes</label><select id="team-count" name="teamCount" class="input"><option value="2">2 equipes</option><option value="3" selected>3 equipes</option><option value="4">4 equipes</option></select></div></div><div class="notice space-top">A data e o horário vêm da configuração da pelada. Os atletas serão distribuídos inicialmente e você poderá ajustar os times.</div><div class="form-actions">${button('Cancelar','dialog-close','secondary')}<button type="submit" class="button">${icon('plus')} Criar evento</button></div></form>`);}
function drawTeamsForm(){openDialog('Sortear os times',`<form id="draw-teams-form"><p class="subtitle">Escolha como distribuir os atletas confirmados nesta pelada.</p><div class="draw-options"><label class="draw-option"><input type="radio" name="mode" value="random" checked><span><strong>Aleatório</strong><small>Embaralha os participantes e distribui entre os times.</small></span></label><label class="draw-option"><input type="radio" name="mode" value="balanced"><span><strong>Equilibrado por nota</strong><small>Usa o overall de cada card para aproximar a força total dos times.</small></span></label></div><p class="footnote">Os nomes dos times são preservados. Um novo sorteio de capitães poderá ser feito em seguida.</p><div class="form-actions">${button('Cancelar','dialog-close','secondary')}<button type="submit" class="button">${icon('players')} Sortear times</button></div></form>`);}
function teamForm(){const r=round();openDialog('Equipes e participantes',`<form id="teams-form"><div class="roster-grid">${r.teams.map(t=>`<div class="roster-team"><div class="field" style="margin-bottom:13px"><label for="team-${e(t.id)}">Nome da equipe</label><input class="input" name="name-${e(t.id)}" id="team-${e(t.id)}" required maxlength="32" value="${e(t.name)}"></div><div class="check-list">${state.athletes.map(a=>`<label class="check-person"><input type="checkbox" name="roster-${e(t.id)}" value="${e(a.id)}" ${t.athleteIds.includes(a.id)?'checked':''}><div><strong>${e(a.nickname||a.name)}</strong><span>${e(positionForRound(state,r,a.id))}</span></div></label>`).join('')}</div></div>`).join('')}</div><p class="field-help">Dê um nome a cada time e escolha seus atletas. Depois, sorteie os capitães: o card de cada capitão será a logo do time.</p><div class="form-actions">${button('Cancelar','dialog-close','secondary')}<button type="submit" class="button">${icon('save')} Salvar equipes</button></div></form>`);}
function showRules(){openDialog('Lances, pontos e evolução',`<div class="rules-grid">${EVENT_RULES.map(r=>`<div class="rule"><span>${e(r.label)}${r.goalkeeperOnly?' · goleiro':''}</span><b class="${r.points<0?'negative':''}">${r.points>0?'+':''}${number(r.points)}</b></div>`).join('')}</div><div class="notice space-top">Uma recuperação é desarme ou interceptação. Defesa de pênalti conta nessa categoria, sem repetir como defesa comum. Uma falha que resulta em gol não recebe também a penalidade menor pelo mesmo erro.</div><p class="footnote">Skills de 1 a 99: evoluem no fechamento, até 1 ponto por atributo por pelada. Finalização, passe e marcação seguem os lances; goleiros têm defesa, reposição e segurança. Ausência de gol ou assistência não reduz skill. Gol sofrido sem falha registrada também não penaliza o goleiro.</p><p class="footnote">O organizador deve registrar cada ação apenas uma vez. Uma assistência deve corresponder a um gol do mesmo time.</p>`);}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function reportPayload(r){return {title:r.title+((r.isDemo||(!accounts.current&&['pelada-01','pelada-02'].includes(r.id)))?' - DEMONSTRAÇÃO':''),date:r.date,modality:MODALITIES[r.modality].label,revision:r.revision||1,closedAt:r.closedAt||new Date().toISOString(),organizer:'Organizador',isClosed:r.status==='closed',matches:r.matches.map(m=>{const s=getMatchScore(r,m.id);return {home:r.teams.find(t=>t.id===m.homeId).name,away:r.teams.find(t=>t.id===m.awayId).name,homeScore:s.home,awayScore:s.away,status:m.status};}),athletes:getRoundStats(state,r.id),fantasy:getFantasyRanking(state,r.id).map(t=>({...t,athleteNames:(t.athleteIds||r.fantasy.find(f=>f.id===t.id)?.athleteIds||[]).map(id=>athlete(id)?.nickname||athlete(id)?.name)})),season:getSeasonRanking(state,r.modality)};}
async function generatePDF(){if(accounts.current&&!await accounts.flush())return;const r=round();notify('Gerando o relatório da pelada…');try{const response=await fetch('/api/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(accounts.current?{roundId:r.id}:reportPayload(r))});if(!response.ok){let data;try{data=await response.json();}catch{}throw new Error(data?.error||'Não foi possível gerar o PDF.');}download(await response.blob(),`fut-parca-${r.date}-v${r.revision||1}.pdf`);notify('PDF gerado. Confira o arquivo nos downloads.');}catch(err){notify(`Resultados salvos. ${err.message} Use “Baixar relatório PDF” para tentar novamente.`,true);}}

document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;if(!isOrganizer()&&adminActions.has(action))return notify('Só o organizador pode realizar esta ação.',true);try{switch(action){case 'toggle-theme':toggleTheme();break;case 'install-app':if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;render();notify(choice.outcome==='accepted'?'Fut Parça instalado na tela inicial.':'Instalação cancelada.');}break;case 'account-login':accountLogin();break;case 'account-register':accountRegister();break;case 'account-group':accountGroup();break;case 'invite-athletes':inviteAthletes();break;case 'create-group':createGroupForm();break;case 'search-groups':await searchGroupsDialog();break;case 'request-join':await accounts.requestJoin(id);notify('Pedido enviado ao organizador.');dialog.close();break;case 'join-requests':await showJoinRequests();break;case 'join-decision':await accounts.decideJoin(id,target.dataset.value);notify(target.dataset.value==='approve'?'Atleta aprovado.':'Pedido recusado.');await accounts.sync();await showJoinRequests();break;case 'account-delete':accountDelete();break;case 'account-logout':await accounts.logout();dialog.close();notify('Você saiu da turma.');break;case 'copy-invite':await navigator.clipboard.writeText(accounts.current.group.inviteCode);notify('ID da pelada copiado.');break;case 'share-invite':{const inviteUrl=new URL(location.origin);inviteUrl.searchParams.set('pelada',accounts.current.group.inviteCode);const payload={title:`Convite para ${accounts.current.group.name}`,text:`Entre na pelada ${accounts.current.group.name} pelo Fut Parça.`,url:inviteUrl.href};if(navigator.share){try{await navigator.share(payload);}catch(err){if(err.name!=='AbortError')throw err;}}else{await navigator.clipboard.writeText(inviteUrl.href);notify('Link da pelada copiado.');}break;}case 'navigate':page=target.dataset.page;search='';render();window.scrollTo({top:0,behavior:'instant'});break;case 'modality':modality=target.dataset.value;render();break;case 'ranking-tab':rankingTab=target.dataset.value;render();break;case 'round-select':activeRoundId=id;activeMatchId=null;selectedFantasyId=null;render();break;case 'match-select':activeMatchId=id;render();break;case 'fantasy-select':selectedFantasyId=id;render();break;case 'new-athlete':athleteForm();break;case 'edit-athlete':athleteForm(id);break;case 'athlete-profile':showProfile(id);break;case 'dialog-close':dialog.close();break;case 'new-round':roundForm();break;case 'toggle-presence':{const r=round(),mine=accounts.current.athleteId,confirmed=new Set(r.confirmedAthleteIds||[]),teams=r.teams.map(t=>({...t,athleteIds:t.athleteIds.filter(x=>x!==mine)}));if(confirmed.has(mine))confirmed.delete(mine);else{confirmed.add(mine);teams.sort((a,b)=>a.athleteIds.length-b.athleteIds.length)[0]?.athleteIds.push(mine);}commit({...state,rounds:state.rounds.map(x=>x.id===r.id?{...r,confirmedAthleteIds:[...confirmed],teams}:x)},confirmed.has(mine)?'Presença confirmada.':'Presença cancelada.');break;}case 'edit-teams':teamForm();break;case 'draw-teams':drawTeamsForm();break;case 'draw-captains':mutate(()=>drawCaptains(state,round().id),'Capitães sorteados. O card de cada um agora é a logo do time.');break;case 'new-fantasy':fantasyForm();break;case 'edit-fantasy':fantasyForm(id);break;case 'rules':showRules();break;case 'camera':await startCamera();break;case 'stop-camera':stopCamera();break;case 'capture-photo':capturePhoto();break;case 'begin-round':mutate(()=>beginRound(state,round().id),'Pelada iniciada. As escalações estão travadas.');break;case 'close-round':if(mutate(()=>closeRound(state,round().id),'Pelada encerrada. Skills e rankings atualizados.')){if(!publicMode||accounts.current)await generatePDF();}break;case 'reopen-round':mutate(()=>reopenRound(state,round().id),'Súmula aberta para correção. Feche novamente para validar a nova versão.');break;case 'remove-event':mutate(()=>removeEvent(state,round().id,id),'Lance removido da súmula.');break;case 'pdf':await generatePDF();break;case 'backup':download(JSON.stringify(state,null,2),`fut-parca-backup-${new Date().toISOString().slice(0,10)}.json`,'application/json');notify('Backup exportado.');break;}}catch(err){notify(err.message,true);}});
document.addEventListener('change',async event=>{const target=event.target;try{if(target.id==='group-schedule-type'){const single=target.value==='single';dialog.querySelectorAll('.schedule-recurring').forEach(field=>field.hidden=single);dialog.querySelectorAll('.schedule-single').forEach(field=>field.hidden=!single);dialog.querySelectorAll('.schedule-recurring [name]').forEach(input=>input.required=!single);dialog.querySelectorAll('.schedule-single [name]').forEach(input=>input.required=single);}if(target.id==='round-picker'){activeRoundId=target.value;activeMatchId=null;selectedFantasyId=null;render();}if(target.classList.contains('match-status'))mutate(()=>setMatchStatus(state,round().id,target.dataset.id,target.value),'Estado do jogo atualizado.');if(target.id==='photo-upload'&&target.files[0])await uploadPhoto(target.files[0]);if(target.id==='register-photo-upload'&&target.files[0]){registerPhotoDraft=await resizePhoto(target.files[0]);document.getElementById('register-photo-preview').src=registerPhotoDraft;}if(target.name==='avatar'){const selected=avatarOptions.find(([id])=>id===target.value);if(selected){registerPhotoDraft='';const preview=document.getElementById('register-photo-preview');if(preview){preview.src=selected[2];preview.alt=`Prévia do ${selected[1]}`;}}}if(target.id==='group-logo-upload'&&target.files[0]){groupLogoDraft=await resizePhoto(target.files[0]);document.getElementById('group-logo-preview').src=groupLogoDraft;}if(target.name==='athleteIds'){const count=dialog.querySelectorAll('[name="athleteIds"]:checked').length;document.getElementById('selected-count').textContent=`${count}/${{futsal:5,society:7,futebol:11}[round().modality]}`;}}catch(err){dialogError(err.message);}});
document.addEventListener('input',event=>{if(event.target.id==='athlete-search'){search=event.target.value;document.getElementById('athlete-grid').innerHTML=athleteGrid();}});
document.addEventListener('submit',event=>{const form=event.target;if(!['event-form','athlete-form','fantasy-form','round-form','teams-form','draw-teams-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form);try{
 if(form.id==='draw-teams-form'){if(!isOrganizer())throw new Error('Só o organizador sorteia os times.');const mode=data.get('mode');if(mutate(()=>drawTeams(state,round().id,mode),mode==='balanced'?'Times equilibrados pela nota dos cards. Sorteie os capitães.':'Times sorteados aleatoriamente. Sorteie os capitães.'))dialog.close();return;}
 if(form.id==='event-form'){if(!isOrganizer())throw new Error('Só o organizador registra os lances.');const playerId=data.get('athleteId'),matchId=activeMatchId,type=data.get('type'),eventId=form.dataset.eventId||(form.dataset.eventId=uid('event'));if(mutate(()=>recordEvent(state,round().id,{id:eventId,matchId,athleteId:playerId,type,createdAt:new Date().toISOString()}),'Lance registrado.')&&type==='goal')celebrateGoal(playerId,matchId);return;}
 if(form.id==='athlete-form'){if(form.dataset.photoBusy==='1')throw new Error('Aguarde o processamento da foto.');const id=form.dataset.id||uid('athlete'),existing=athlete(id),preferences=Object.fromEntries(Object.keys(MODALITIES).map(m=>[m,{primary:data.get(`primary-${m}`),secondary:data.get(`secondary-${m}`)||''}])),base=Object.fromEntries(Object.keys(MODALITIES).map(m=>[m,Object.fromEntries(['rit','fin','pas','con','def','fis','div','han','kic','ref','spd','pos'].map(k=>[k,60]))])),a={...existing,id,name:data.get('name').trim(),nickname:data.get('nickname').trim(),contact:data.get('contact').trim(),photo:photoDraft,preferences,baseSkills:existing?.baseSkills||base};if(!a.name||!a.nickname||!a.contact)throw new Error('Preencha nome, apelido e contato.');if(!a.contact.includes('@')&&!/^[+()\d\s.-]{8,25}$/.test(a.contact))throw new Error('Informe um e-mail ou telefone válido.');commit({...state,athletes:existing?state.athletes.map(x=>x.id===id?a:x):[...state.athletes,a]},'Perfil do atleta salvo.');dialog.close();return;}
 if(form.id==='fantasy-form'){const payload={id:form.dataset.id||uid('fantasy'),name:data.get('name').trim(),owner:data.get('owner').trim(),athleteIds:data.getAll('athleteIds'),...(accounts.current?{ownerUserId:accounts.current.user.id}:{})};if(!payload.name||!payload.owner)throw new Error('Preencha o nome do time e seu nome.');const next=saveFantasy(state,round().id,payload);const savedLineup=next.rounds.find(r=>r.id===round().id).fantasy.find(t=>t.id===payload.id);if(accounts.current)savedLineup.ownerUserId=payload.ownerUserId;selectedFantasyId=payload.id;commit(next,'Escalação confirmada.');dialog.close();return;}
 if(form.id==='round-form'){const id=uid('round'),m=data.get('modality'),count=Number(data.get('teamCount')),teams=Array.from({length:count},(_,i)=>({id:uid('team'),name:['Resenha FC','Boleiros FC','Parças FC','Canela FC'][i],color:['#386b47','#c08a44','#627ca0','#9b5975'][i],athleteIds:[]})),gks=state.athletes.filter(a=>positionOf(a,m)==='Goleiro'),field=state.athletes.filter(a=>positionOf(a,m)!=='Goleiro');gks.forEach((a,i)=>teams[i%count].athleteIds.push(a.id));field.forEach((a,i)=>teams[i%count].athleteIds.push(a.id));const matches=[];for(let i=0;i<count;i++)for(let j=i+1;j<count;j++)matches.push({id:uid('match'),homeId:teams[i].id,awayId:teams[j].id,status:'scheduled'});const r={id,title:data.get('title').trim(),date:data.get('date'),time:data.get('time'),confirmedAthleteIds:accounts.current?[accounts.current.athleteId]:[],modality:m,status:'draft',revision:0,teams,matches,events:[],fantasy:[]};if(!r.title)throw new Error('Informe o nome da pelada.');activeRoundId=id;activeMatchId=null;page='rounds';commit({...state,rounds:[r,...state.rounds]},'Nova pelada criada. Confira as equipes antes de começar.');dialog.close();return;}
 if(form.id==='teams-form'){const r=round(),used=new Set(),teams=r.teams.map(t=>{const ids=data.getAll(`roster-${t.id}`);for(const id of ids){if(used.has(id))throw new Error(`${athlete(id).nickname} foi escolhido em mais de uma equipe.`);used.add(id);}const name=data.get(`name-${t.id}`).trim();if(!name)throw new Error('Informe o nome de todas as equipes.');return {...t,name,athleteIds:ids,captainId:ids.includes(t.captainId)?t.captainId:null};});const confirmed=new Set(teams.flatMap(t=>t.athleteIds));if(r.fantasy.some(t=>t.athleteIds.some(id=>!confirmed.has(id))))throw new Error('Uma escalação usa atleta que seria removido. Ajuste o fantasy antes de alterar as equipes.');commit({...state,rounds:state.rounds.map(x=>x.id===r.id?{...r,teams}:x)},'Equipes atualizadas.');dialog.close();return;}
 }catch(err){dialogError(err.message);}});
dialog.addEventListener('close',()=>{photoJob++;stopCamera();});dialog.addEventListener('cancel',()=>{photoJob++;stopCamera();});
function accountLogin(){openDialog('Entrar na turma',`<form id="login-form"><div class="form-grid"><div class="field full"><label for="login-email">E-mail da conta</label><input type="email" class="input" id="login-email" name="email" autocomplete="username" required></div><div class="field full"><label for="login-password">Senha</label><input type="password" class="input" id="login-password" name="password" autocomplete="current-password" required></div></div><p class="footnote">Entre para acessar os atletas, jogos e escalações da sua turma.</p><div class="form-actions">${button('Criar minha conta','account-register','secondary')}<button class="button" type="submit">Entrar</button></div></form>`);}
function accountRegister(){registerPhotoDraft='';openDialog('Crie seu perfil de atleta',`<form id="register-form">${pendingInviteCode?`<input type="hidden" name="inviteCode" value="${e(pendingInviteCode)}">`:''}<div class="form-grid"><div class="field"><label for="account-name">Nome completo</label><input class="input" id="account-name" name="name" autocomplete="name" required maxlength="70"></div><div class="field"><label for="account-nickname">Apelido no card</label><input class="input" id="account-nickname" name="nickname" required maxlength="18"></div><div class="field"><label for="account-email">E-mail</label><input type="email" class="input" id="account-email" name="email" autocomplete="email" required maxlength="100"></div><div class="field"><label for="account-contact">Telefone (opcional)</label><input class="input" id="account-contact" name="contact" autocomplete="tel" maxlength="25"></div><div class="field"><label for="account-sex">Sexo</label><select class="input" id="account-sex" name="sex" required><option value="">Selecione</option><option value="masculino">Masculino</option><option value="feminino">Feminino</option><option value="nao-binario">Não binário</option><option value="prefiro-nao-informar">Prefiro não informar</option></select></div><div class="field"><label for="account-birth">Data de nascimento</label><input type="date" class="input" id="account-birth" name="birthDate"></div><div class="field full"><label for="account-password">Crie sua senha</label><input type="password" class="input" id="account-password" name="password" autocomplete="new-password" required minlength="8"><p class="field-help">Pelo menos 8 caracteres.</p></div><div class="field full"><label>Foto ou avatar</label><div class="photo-options"><img id="register-photo-preview" class="photo-preview" src="./avatar-1.png" alt="Prévia do Avatar 1"><label class="button secondary file-button">Enviar foto<input type="file" id="register-photo-upload" accept="image/jpeg,image/png,image/webp"></label></div><div class="avatar-grid">${avatarOptions.map(x=>avatarThumb(...x)).join('')}</div><p class="field-help">Escolha um avatar ou envie sua foto. Ao escolher outro avatar, a foto enviada é removida da prévia.</p></div>${Object.entries(MODALITIES).map(([m,x])=>`<div class="field"><label>${e(x.label)} · posição</label><select class="input" name="primary-${m}">${x.positions.map(p=>`<option>${e(p)}</option>`).join('')}</select></div>`).join('')}</div><div class="notice space-top">${pendingInviteCode?`Seu cadastro entrará diretamente na pelada do convite <strong>${e(pendingInviteCode)}</strong>.`:'Depois do cadastro você poderá criar sua pelada ou buscar uma existente e pedir autorização.'}</div><div class="form-actions">${button('Já tenho conta','account-login','secondary')}<button class="button" type="submit">${icon('players')} ${pendingInviteCode?'Criar perfil e entrar':'Criar conta'}</button></div></form>`);}
function inviteAthletes(){const session=accounts.current;if(!session||!isOrganizer())return;const inviteUrl=new URL(location.origin);inviteUrl.searchParams.set('pelada',session.group.inviteCode);openDialog('Convidar atletas',`<div class="eyebrow">CONVITE DA PELADA</div><h2>${e(session.group.name)}</h2><p class="subtitle">Envie o link ou informe o ID para o atleta buscar no Fut Parça.</p><section class="notice space-top"><strong>ID da pelada</strong><div class="row spread" style="margin-top:13px"><strong style="font-size:23px;letter-spacing:3px">${e(session.group.inviteCode)}</strong>${button('Copiar ID','copy-invite','secondary')}</div></section><div class="field space-top"><label for="invite-link">Link para entrar</label><input id="invite-link" class="input" value="${e(inviteUrl.href)}" readonly></div><div class="form-actions">${button('Fechar','dialog-close','secondary')}${button('Enviar link','share-invite','lime')}</div><p class="footnote">Quem ainda não tiver conta será levado ao cadastro e entrará na pelada pelo convite.</p>`);}
function accountGroup(){const session=accounts.current;if(!session)return accountLogin();openDialog(e(session.group.name),`<div class="eyebrow">${isOrganizer()?'Você organiza essa pelada':'Você faz parte dessa turma'}</div><h2>${e(session.user.name)}</h2><p class="subtitle">${e(session.user.email)}</p>${isOrganizer()?`<section class="notice space-top"><strong>ID e convite da pelada</strong><p class="field-help">Os atletas podem buscar por este ID ou entrar pelo link.</p><div class="row spread" style="margin-top:13px"><strong style="font-size:23px;letter-spacing:3px">${e(session.group.inviteCode)}</strong><div class="row">${button('Copiar ID','copy-invite','secondary')}${button('Compartilhar link','share-invite','lime')}</div></div></section>`:''}<p class="footnote">${state.athletes.length} atletas cadastrados · ${state.rounds.length} peladas. Os dados da turma ficam salvos no servidor. <a href="/excluir-conta.html">Privacidade e exclusão</a>.</p><div class="form-actions">${button('Meu perfil','athlete-profile','secondary',`data-id="${e(session.athleteId)}"`)}${isOrganizer()?button('Pedidos para entrar','join-requests','secondary'):''}${button('Sair da conta','account-logout','secondary')}${button('Excluir minha conta','account-delete','danger')}</div>`);}
function createGroupForm(){groupLogoDraft='';const today=isoDate(new Date());openDialog('Criar minha pelada',`<form id="create-group-form"><div class="form-grid"><div class="field full"><label for="group-name">Nome da pelada</label><input class="input" id="group-name" name="name" required maxlength="80" placeholder="Pelada dos Parças"></div><div class="field full"><label for="group-schedule-type">Como esta pelada acontece?</label><select class="input" id="group-schedule-type" name="scheduleType"><option value="recurring">Pelada fixa · acontece toda semana</option><option value="single">Pelada avulsa · acontece uma única vez</option></select></div><div class="field schedule-recurring"><label for="group-weekly-day">Dia da semana</label><select class="input" id="group-weekly-day" name="weeklyDay" required>${['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field schedule-recurring"><label for="group-weekly-time">Horário fixo</label><input class="input" id="group-weekly-time" type="time" name="weeklyTime" required value="20:00"></div><div class="field schedule-single" hidden><label for="group-single-date">Data única</label><input class="input" id="group-single-date" type="date" name="singleDate" value="${e(today)}"></div><div class="field schedule-single" hidden><label for="group-single-time">Horário</label><input class="input" id="group-single-time" type="time" name="singleTime" value="20:00"></div><div class="field full group-logo-field"><label>Logo ou foto da pelada</label><div class="photo-options"><img id="group-logo-preview" class="photo-preview group-logo-preview" src="./logo-fut-parca.jpeg" alt="Prévia da logo da pelada"><div><label class="button secondary file-button">${icon('plus')} Escolher logo<input type="file" id="group-logo-upload" accept="image/jpeg,image/png,image/webp" aria-label="Escolher logo da pelada"></label><p class="field-help">JPG, PNG ou WebP. Se não escolher, o Fut Parça usa a logo padrão.</p></div></div></div></div><div class="form-actions">${button('Cancelar','dialog-close','secondary')}<button class="button" type="submit">Criar pelada</button></div></form>`);}
async function searchGroupsDialog(query=''){const groups=await accounts.searchGroups(query);openDialog('Buscar pelada',`<form id="group-search-form"><div class="row"><input class="input" name="query" placeholder="Nome ou ID da pelada" aria-label="Nome ou ID da pelada" value="${e(query)}"><button class="button" type="submit">Buscar</button></div></form><div class="space-top">${groups.length?groups.map(g=>`<div class="event"><div class="search-group-info">${g.logo?`<img class="search-group-logo" src="${e(g.logo)}" alt="">`:''}<div><strong>${e(g.name)}</strong><span class="event-meta">ID ${e(g.publicId)} · ${g.scheduleType==='single'?`${date(g.singleDate)} às ${e(g.singleTime)}`:`${e(g.weeklyDay)} às ${e(g.weeklyTime)}, toda semana`} · ${g.members} atleta(s)</span></div></div>${button('Pedir para entrar','request-join','secondary',`data-id="${e(g.id)}"`)}</div>`).join(''):empty('Nenhuma pelada encontrada','Confira o nome ou ID e tente novamente.')}</div>`);}
async function showJoinRequests(){const requests=await accounts.joinRequests();openDialog('Pedidos para entrar',requests.length?requests.map(r=>`<div class="event"><div><strong>${e(r.nickname||r.name)}</strong><span class="event-meta">${e(r.name)}</span></div><div class="row">${button('Aprovar','join-decision','',`data-id="${e(r.id)}" data-value="approve"`)}${button('Recusar','join-decision','secondary',`data-id="${e(r.id)}" data-value="reject"`)}</div></div>`).join(''):empty('Nenhum pedido pendente','Quando alguém pedir para entrar, aparecerá aqui.'));}
function accountDelete(){const session=accounts.current;if(!session)return accountLogin();openDialog('Excluir minha conta',`<form id="delete-account-form"><div class="notice error"><strong>Esta ação é permanente.</strong><br>${isOrganizer()?'Se houver outros membros, um deles se tornará organizador. Se você estiver sozinho, a turma também será excluída.':'Sua conta será removida da turma.'} Seu perfil será apagado ou anonimizado nos resultados históricos.</div><div class="form-grid space-top"><div class="field full"><label for="delete-password">Confirme sua senha</label><input type="password" class="input" id="delete-password" name="password" autocomplete="current-password" required></div><div class="field full"><label for="delete-confirmation">Digite EXCLUIR</label><input class="input" id="delete-confirmation" name="confirmation" autocomplete="off" required pattern="EXCLUIR"></div></div><div class="form-actions">${button('Cancelar','account-group','secondary')}<button class="button danger" type="submit">Excluir definitivamente</button></div></form>`);}
document.addEventListener('submit',async event=>{const form=event.target;if(!['login-form','register-form','delete-account-form','create-group-form','group-search-form'].includes(form.id))return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type="submit"]');submit.disabled=true;try{if(form.id==='group-search-form'){await searchGroupsDialog(data.query);return;}if(form.id==='create-group-form'){await accounts.createGroup({...data,logo:groupLogoDraft});dialog.close();notify('Pelada criada. Agora compartilhe o link com os parças!');return;}if(form.id==='login-form'){await accounts.login(data);const joined=await consumeInvite();dialog.close();if(!joined)notify('Sua turma está pronta. Bora pra pelada!');}else if(form.id==='register-form'){data.profile={nickname:data.nickname,contact:data.contact||data.email,sex:data.sex,birthDate:data.birthDate,photo:registerPhotoDraft,avatar:data.avatar,preferences:Object.fromEntries(Object.keys(MODALITIES).map(m=>[m,{primary:data[`primary-${m}`],secondary:''}]))};await accounts.register(data);const joinedByLink=Boolean(data.inviteCode);if(joinedByLink)clearInvite();dialog.close();notify(joinedByLink?'Perfil criado. Você já entrou na pelada!':'Perfil criado. Agora crie ou encontre sua pelada!');}else{if(data.confirmation!=='EXCLUIR')throw new Error('Digite EXCLUIR para confirmar.');await accounts.deleteAccount({password:data.password});dialog.close();notify('Sua conta e seus dados pessoais foram excluídos.');}}catch(err){dialogError(err.message);}finally{submit.disabled=false;}});
try { const configResponse=await fetch('/api/config'); if(configResponse.ok)publicMode=(await configResponse.json()).public===true; } catch {}
await accounts.ready();
if(pendingInviteCode&&needsPelada()){try{await consumeInvite();}catch(err){notify(err.message,true);}}
else if(pendingInviteCode&&accounts.current&&!needsPelada())clearInvite();
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;render();});
window.addEventListener('appinstalled',()=>{installPrompt=null;render();notify('Fut Parça instalado. Bora pra pelada!');});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
window.addEventListener('focus',()=>{if(!dialog.open)accounts.sync();});
setInterval(()=>{if(!dialog.open)accounts.sync();},15000);
try{render();}catch(err){app.innerHTML=`<div class="loading">Não foi possível abrir o Fut Parça.<span>${e(err.message)}</span></div>`;console.error(err);}




